<script setup lang="ts">
import type { PredictionDay } from '~/types/plots'
interface Verification {id:string;station_id:string;station_name:string;target_date:string;issued_at:string;verified_at:string|null;predicted:PredictionDay;observed:Record<string,number|null>;observation_coverage:Record<string,number>}
const {request}=useApi(),{dateTime}=useViewerTime()
const items=ref<Verification[]>([]),total=ref(0),offset=ref(0),busy=ref(false),error=ref(''),station=ref(''),from=ref(''),to=ref('')
const stations=ref<{id:string;name:string}[]>([]),schedule=ref<{hour:number;minute:number;timezone:string}>()
const labels:Record<string,string>={temperature_avg_c:'Temperatura media',temperature_min_c:'Temperatura mínima',temperature_max_c:'Temperatura máxima',humidity_pct:'Humedad del aire',precipitation_mm:'Lluvia',wind_speed_ms:'Viento medio',evapotranspiration_mm:'Evapotranspiración',soil_temperature_avg_c:'Temperatura del suelo',soil_moisture_pct:'Humedad del suelo (modelo)',soil_tension_cb:'Tensión del suelo',leaf_wetness_hours:'Mojado foliar (estimado)'}
const format=(v:number|null|undefined)=>v==null?'Pendiente / sin sensor comparable':v.toLocaleString('es-PY',{maximumFractionDigits:2})
async function load(reset=false){if(reset)offset.value=0;busy.value=true;error.value='';try{const query=new URLSearchParams({limit:'30',offset:String(offset.value)});if(station.value)query.set('station_id',station.value);if(from.value)query.set('date_from',from.value);if(to.value)query.set('date_to',to.value);const result=await request<{items:Verification[];total:number;schedule:typeof schedule.value}>(`/forecasts/verification?${query}`);items.value=result.items;total.value=result.total;schedule.value=result.schedule}catch{error.value='No se pudo cargar la comparación de predicciones.'}finally{busy.value=false}}
onMounted(async()=>{await load();try{const result=await request<{items:{id:string;name:string}[]}>('/stations?limit=500');stations.value=result.items}catch{}})
async function page(delta:number){offset.value+=delta;await load()}
</script>
<template><section class="panel prediction-audit"><h2>Predicción y resultado diario</h2><p>La última previsión emitida antes de comenzar cada día se conserva para compararla con la estación. Las mediciones pendientes se completan en segundo plano.</p><small v-if="schedule">Actualización diaria: {{String(schedule.hour).padStart(2,'0')}}:{{String(schedule.minute).padStart(2,'0')}} · {{schedule.timezone}}.</small>
 <form class="prediction-filters" @submit.prevent="load(true)"><label>Estación<select v-model="station" class="select"><option value="">Todas</option><option v-for="s in stations" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Desde<input v-model="from" type="date" class="input"></label><label>Hasta<input v-model="to" type="date" class="input"></label><button class="btn btn-light" :disabled="busy">{{busy?'Consultando…':'Consultar'}}</button></form>
 <p v-if="error" role="alert">{{error}}</p><p v-else-if="!items.length&&!busy">Aún no hay predicciones registradas. Se guardarán al analizar una parcela y en la ejecución diaria.</p>
 <div class="verification-table"><table v-if="items.length"><thead><tr><th>Día / estación</th><th>Variable</th><th>Valor predicho</th><th>Valor obtenido</th></tr></thead><tbody><template v-for="item in items" :key="item.id"><tr v-for="(value,key) in item.predicted.variables" :key="`${item.id}-${key}`"><td><b>{{item.target_date}}</b><br>{{item.station_name}}<small>Emitido: {{dateTime(item.issued_at)}}</small></td><td>{{labels[key]||key}}</td><td>{{format(value.value)}} {{value.unit}}<small>{{value.method==='combined'?'Estación + Open-Meteo':value.method==='station_trend'?'Tendencia de estación':'Open-Meteo'}} · historial {{value.history_days??0}} días</small></td><td>{{item.observed?.[key]!=null?`${format(item.observed[key])} ${value.unit}`:format(null)}}<small v-if="item.observation_coverage?.[key]!=null">Cobertura: {{Math.round(item.observation_coverage[key]*100)}} %</small></td></tr></template></tbody></table></div>
 <div v-if="total>30" class="prediction-pagination"><button class="btn btn-light" :disabled="busy||offset===0" @click="page(-30)">Anterior</button><span>{{offset+1}}–{{Math.min(offset+30,total)}} de {{total}} días/estación</span><button class="btn btn-light" :disabled="busy||offset+30>=total" @click="page(30)">Siguiente</button></div>
</section></template>
<style scoped>.prediction-audit{margin-bottom:24px;padding:22px}.prediction-audit p,.prediction-audit>small{color:var(--fc-muted,#64748b)}.prediction-filters{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:20px 0}.prediction-filters label{display:grid;gap:6px;font-size:.85rem}.verification-table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.85rem}th,td{text-align:left;padding:12px;border-bottom:1px solid #dce6eb;vertical-align:top}th{background:#f1f6f8}td small{display:block;margin-top:5px;font-size:.72rem;color:#64748b}.prediction-pagination{display:flex;align-items:center;gap:12px;justify-content:space-between;margin-top:16px}</style>
